import csv, os

def output_root():
    for c in [os.getcwd(), "/case/submission"]:
        if c and os.path.isfile(os.path.join(c, "backbone_rmsd.csv")):
            return c
    raise SystemExit("output root not found")

root = output_root()

def read_rows(p):
    with open(p, newline="") as fh:
        rd = csv.DictReader(fh)
        return list(rd), list(rd.fieldnames)

def write_rows(p, rows, fieldnames):
    with open(p, "w", newline="") as fh:
        w = csv.DictWriter(fh, fieldnames=fieldnames)
        w.writeheader()
        for r in rows:
            w.writerow(r)

tol = lambda v: 5e-6 + 1e-6*abs(v)

# backbone_rmsd.csv: swap LID and NMP domain results (wrong domain identity)
path = os.path.join(root, "backbone_rmsd.csv")
rows, names = read_rows(path)
assert names[:5] == ["Frame","Backbone","CORE","LID","NMP"], names
for r in rows:
    r["LID"], r["NMP"] = r["NMP"], r["LID"]
ndiff = sum(1 for r in rows
            if abs(float(r["LID"]) - float(r["NMP"])) > tol(float(r["NMP"])))
assert ndiff >= 90, ndiff
# ... and perturb the fitting-group / CORE results coherently, as would occur
# with a fitting group defined on a wrong subset of the backbone atoms
for r in rows:
    if float(r["Backbone"]) > 1e-3:
        r["Backbone"] = repr(float(r["Backbone"]) * 1.005)
    if float(r["CORE"]) > 1e-3:
        r["CORE"] = repr(float(r["CORE"]) * 1.01)
write_rows(path, rows, names)
print("backbone_rmsd.csv: LID/NMP swapped (%d rows over tol), Backbone/CORE scaled" % ndiff)

import csv, os

def output_root():
    for c in [os.getcwd(), "/case/submission"]:
        if c and os.path.isfile(os.path.join(c, "mass_weighted_rmsd.csv")):
            return c
    raise SystemExit("output root not found")

root = output_root()

def read_rows(p):
    with open(p, newline="") as fh:
        rd = csv.DictReader(fh)
        return list(rd), list(rd.fieldnames)

tol = lambda v: 5e-6 + 1e-6*abs(v)
path = os.path.join(root, "mass_weighted_rmsd.csv")
path_e = os.path.join(root, "resid_weighted_rmsd.csv")
mw, mn = read_rows(path)
rw, rn = read_rows(path_e)
assert mn == rn == ["Frame","C-alphas","CORE","LID","NMP"], (mn, rn)
worse = sum(1 for m, r in zip(mw, rw) for c in ["C-alphas","CORE","LID","NMP"]
            if abs(float(m[c]) - float(r[c])) > tol(float(r[c])))
assert worse >= 90, worse
for m, r in zip(mw, rw):
    assert m["Frame"] == r["Frame"]
    for c in ["C-alphas","CORE","LID","NMP"]:
        m[c] = r[c]
with open(path, "w", newline="") as fh:
    w = csv.DictWriter(fh, fieldnames=mn)
    w.writeheader()
    for r in mw:
        w.writerow(r)
print("mass_weighted_rmsd.csv: replaced with resid-weighted values (%d cells over tol)" % worse)

import csv, os

def output_root():
    for c in [os.getcwd(), "/case/submission"]:
        if c and os.path.isfile(os.path.join(c, "backbone_rmsd.csv")):
            return c
    raise SystemExit("output root not found")

root = output_root()

def read_rows(p):
    with open(p, newline="") as fh:
        rd = csv.DictReader(fh)
        return list(rd), list(rd.fieldnames)

def write_rows(p, rows, fieldnames):
    with open(p, "w", newline="") as fh:
        w = csv.DictWriter(fh, fieldnames=fieldnames)
        w.writeheader()
        for r in rows:
            w.writerow(r)

# Contract-compliant representation changes: (1) extra ignored column
# ("Time" derived from the timestep, explicitly permitted) and reversed
# physical row order (rows are joined by Frame, order is not compared);
# (2) values re-serialized at %.15g, well inside the 5e-6 + 1e-6*|v| floor.
for fn in ["backbone_rmsd.csv","mass_weighted_rmsd.csv","resid_weighted_rmsd.csv",
           "ca_core_rmsd.csv"]:
    rows, names = read_rows(os.path.join(root, fn))
    for r in rows:
        for k in r:
            if k != "Frame":
                r[k] = "%.15g" % float(r[k])
    out = [dict(r, Time=0.02*int(r["Frame"])) for r in rows]
    out.reverse()
    write_rows(os.path.join(root, fn), out, names + ["Time"])
    print("representation: %s reversed, Time column added, float values" % fn)

path = os.path.join(root, "open_closed_backbone_rmsd.csv")
rows, names = read_rows(path)
rows[0]["Backbone"] = "%.15g" % float(rows[0]["Backbone"])
write_rows(path, rows, names)
print("representation: open_closed_backbone_rmsd.csv re-serialized")
